/*
 * A106749  Define the morphism f: 1->113, 2->13, 3->2; sequence gives
 *          trajectory of 1 under f.
 * https://oeis.org/A106749
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   the sequence is generated by the morphism f: 1 → 113, 2 → 13, 3
 *            → 2, starting with 1 and taking the nth symbol of the infinite
 *            fixed point
 * Range:     u8 n <= 104, u16 n <= 104, u32 n <= 104, u64 n <= 104,
 *            u128 n <= 104, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *word = NULL;
    static idx_t word_len = 0;

    /* initialise with the first symbol */
    if (word_len == 0) {
        word = (seq_t*)malloc(sizeof(seq_t));
        if (!word) return (seq_t)0;          /* fallback */
        word[0] = (seq_t)1;
        word_len = 1;
    }

    /* grow the word until it covers the requested index */
    while (n >= word_len) {
        idx_t old_len = word_len;
        idx_t new_len = 0;

        /* compute the length of the next word */
        for (idx_t i = 0; i < old_len; ++i) {
            seq_t v = word[i];
            if (v == (seq_t)1)            new_len += 3;
            else if (v == (seq_t)2)       new_len += 2;
            else /* v == 3 */              new_len += 1;
        }

        /* allocate new storage */
        seq_t *new_word = (seq_t*)malloc(sizeof(seq_t) * new_len);
        if (!new_word) return (seq_t)0;    /* fallback on allocation failure */

        /* fill the new word by applying the morphism */
        idx_t pos = 0;
        for (idx_t i = 0; i < old_len; ++i) {
            seq_t v = word[i];
            if (v == (seq_t)1) {
                new_word[pos++] = (seq_t)1;
                new_word[pos++] = (seq_t)1;
                new_word[pos++] = (seq_t)3;
            } else if (v == (seq_t)2) {
                new_word[pos++] = (seq_t)1;
                new_word[pos++] = (seq_t)3;
            } else {  /* v == 3 */
                new_word[pos++] = (seq_t)2;
            }
        }

        /* replace the old word */
        free(word);
        word = new_word;
        word_len = new_len;
    }

    return word[n];
}
